method below_zero(operations: seq<int>) returns (s:array<int>, result:bool)
    ensures s.Length == |operations| + 1
    ensures s[0] == 0
    ensures forall i :: 0 <= i < |operations| ==> s[i + 1] == s[i] + operations[i]
    ensures result <==> exists i :: 0 <= i < |operations| && s[i + 1] < 0
    ensures !result ==> forall i :: 0 <= i < |operations| ==> s[i + 1] >= 0
{
    var n := |operations|;
    s := new int[n + 1];
    s[0] := 0;
    var hasBelowZero := false;
    var i := 0;

    while i < n 
        invariant 0 <= i <= n
        invariant s.Length == n + 1
        invariant s[0] == 0
        invariant forall k :: 0 <= k < i ==> s[k + 1] == s[k] + operations[k]
        invariant hasBelowZero <==> exists k :: 0 <= k < i && s[k + 1] < 0
        invariant !hasBelowZero ==> forall k :: 0 <= k < i ==> s[k + 1] >= 0
    {
        s[i + 1] := s[i] + operations[i];
        if s[i + 1] < 0 {
            hasBelowZero := true;
        }
        i := i + 1;
    }

    result := hasBelowZero;
}

