method CanyonSearch(a: array<int>, b: array<int>) returns (d: nat)
  requires a.Length != 0 && b.Length != 0
  requires forall i, j :: 0 <= i < j < a.Length ==> a[i] <= a[j]
  requires forall i, j :: 0 <= i < j < b.Length ==> b[i] <= b[j]
  ensures exists i, j :: 0 <= i < a.Length && 0 <= j < b.Length && d == if a[i] - b[j] >= 0 then a[i] - b[j] else b[j] - a[i]
  ensures forall i, j :: 0 <= i < a.Length && 0 <= j < b.Length ==> d <= if a[i] - b[j] >= 0 then a[i] - b[j] else b[j] - a[i]
{
  var minDiff := if a[0] - b[0] >= 0 then a[0] - b[0] else b[0] - a[0];
  var i := 0;
  var j := 0;

  while i < a.Length && j < b.Length
    invariant 0 <= i <= a.Length
    invariant 0 <= j <= b.Length
    invariant forall x, y :: 0 <= x < i && 0 <= y < b.Length ==> minDiff <= if a[x] - b[y] >= 0 then a[x] - b[y] else b[y] - a[x]
    invariant forall x, y :: 0 <= x < a.Length && 0 <= y < j ==> minDiff <= if a[x] - b[y] >= 0 then a[x] - b[y] else b[y] - a[x]
    invariant exists x, y :: 0 <= x < a.Length && 0 <= y < b.Length && minDiff == if a[x] - b[y] >= 0 then a[x] - b[y] else b[y] - a[x]
  {
    var diff := if a[i] - b[j] >= 0 then a[i] - b[j] else b[j] - a[i];
    if diff < minDiff {
      minDiff := diff;
    }
    // Move the pointer which can reduce the difference
    if i < a.Length && j < b.Length && a[i] < b[j] {
      i := i + 1;
    } else {
      j := j + 1;
    }
  }

  d := minDiff;
}

method copy(src: array<int>, sStart: nat, dest: array<int>, dStart: nat, len: nat) returns (r: array<int>)
  requires src.Length >= sStart + len
  requires dest.Length >= dStart + len
  ensures r.Length == dest.Length
  ensures forall i :: 0 <= i < dest.Length && (i < dStart || i >= dStart + len) ==> r[i] == dest[i]
  ensures forall i :: 0 <= i < len ==> r[dStart + i] == src[sStart + i]
{
  r := new int[dest.Length];
  var i := 0;

  // Copy initial unchanged part of 'dest' up to 'dStart'
  while i < dStart
    invariant 0 <= i <= dStart
    invariant r.Length == dest.Length
    invariant forall k :: 0 <= k < i ==> r[k] == dest[k]
  {
    r[i] := dest[i];
    i := i + 1;
  }

  // Copy 'len' elements from 'src' starting at 'sStart' to 'r' starting at 'dStart'
  while i < dStart + len
    invariant dStart <= i <= dStart + len
    invariant r.Length == dest.Length
    invariant forall k :: 0 <= k < dStart ==> r[k] == dest[k]
    invariant forall k :: dStart <= k < i ==> r[k] == src[sStart + k - dStart]
  {
    r[i] := src[sStart + i - dStart];
    i := i + 1;
  }

  // Copy remaining unchanged part of 'dest' after 'dStart + len' to 'r'
  while i < dest.Length
    invariant dStart + len <= i <= dest.Length
    invariant r.Length == dest.Length
    invariant forall k :: 0 <= k < dStart ==> r[k] == dest[k]
    invariant forall k :: dStart <= k < dStart + len ==> r[k] == src[sStart + k - dStart]
    invariant forall k :: dStart + len <= k < i ==> r[k] == dest[k]
  {
    r[i] := dest[i];
    i := i + 1;
  }
}

