method SquareRoot(N:nat) returns (r:nat)
    ensures r * r <= N < (r + 1) * (r + 1)
{
    var low := 0;
    var high := N + 1;

    // Invariant: low^2 <= N < high^2
    while low + 1 < high
        invariant 0 <= low <= high <= N + 1
        invariant low * low <= N
        invariant high * high > N
    {
        var mid := (low + high) / 2;

        if mid * mid <= N {
            low := mid;
        } else {
            high := mid;
        }
    }

    r := low;
}

method ComputeIsEven(x:int) returns (is_even:bool)
    ensures is_even <==> x % 2 == 0
{
    var abs_x := if x < 0 then -x else x; // Use absolute value of x
    var remainder := abs_x;

    while remainder > 1
        invariant 0 <= remainder <= abs_x // Remainder is non-negative and within bounds
        invariant remainder % 2 == abs_x % 2 // Parity (even or odd) of remainder matches that of abs_x
    {
        remainder := remainder - 2;
    }

    is_even := remainder == 0;
}

method IsPalindrome(x: seq<char>) returns (result: bool)
