method LongestCommonPrefix(str1: seq<char>, str2: seq<char>) returns (prefix: seq<char>)
    ensures |prefix| <= |str1|
    ensures |prefix| <= |str2|
    ensures prefix == str1[..|prefix|] && prefix == str2[..|prefix|]
    ensures |prefix| == |str1| || |prefix| == |str2| || (|prefix| < |str1| && |prefix| < |str2| && str1[|prefix|] != str2[|prefix|])
{
    var i: nat := 0;
    prefix := [];

    while i < |str1| && i < |str2| && str1[i] == str2[i]
        invariant 0 <= i <= |str1| && 0 <= i <= |str2|
        invariant prefix == str1[..i] && prefix == str2[..i]
        decreases |str1| - i, |str2| - i
    {
        prefix := prefix + [str1[i]];
        i := i + 1;
    }
}

