  var i := 1;

  while i < a.Length
    invariant 1 <= i <= a.Length
    invariant exists j :: 0 <= j < i && a[j] == m
    invariant forall j :: 0 <= j < i ==> a[j] <= m
  {
    if a[i] > m {
      m := a[i];
    }
    i := i + 1;
  }
}

method Quotient(x: nat, y: nat) returns (r: int, q: int)
  requires y != 0
  ensures r >= 0
  ensures q >= 0
  ensures r < y
  ensures x == q * y + r
{
  r := x;
  q := 0;

  while r >= y
    invariant r >= 0
    invariant q >= 0
    invariant x == q * y + r
  {
    r := r - y;
    q := q + 1;
  }
}

