method rotate(a: array<int>, offset: int) returns (b: array<int>)
  requires 0 <= offset
  ensures b.Length == a.Length
  ensures forall i :: 0 <= i < a.Length ==> b[i] == a[(i + offset) % a.Length]
{
  b := new int[a.Length];
  var i: int := 0;

  while i < a.Length
    invariant 0 <= i <= a.Length
    invariant b.Length == a.Length
    invariant forall j :: 0 <= j < i ==> b[j] == a[(j + offset) % a.Length]
  {
    b[i] := a[(i + offset) % a.Length];
    i := i + 1;
  }
}

method SwapArithmetic(X: int, Y: int) returns(x: int, y: int)
    ensures x == Y
    ensures y == X
{
    var a := X;
    var b := Y;

    // Swap using arithmetic without introducing new variables
    var i := 0;
    while i < 3
        invariant i >= 0 && i <= 3
        invariant (i == 0 ==> a == X && b == Y)
        invariant (i == 1 ==> a == X + Y && b == Y)
        invariant (i == 2 ==> a == X + Y && b == X)
        invariant (i == 3 ==> a == Y && b == X)
    {
        if i == 0 {
            a := a + b;
        } else if i == 1 {
            b := a - b;
        } else if i == 2 {
            a := a - b;
        }
        i := i + 1;
    }

    x := a;
    y := b;
}

