method SwapSimultaneous(X: int, Y: int) returns(x: int, y: int)
    requires true
    ensures x == Y
    ensures y == X
{
    var a := X;
    var b := Y;
    var step := 0;

    while step < 1 // loop to ensure simultaneous swap
        invariant 0 <= step <= 1
        invariant (step == 0 && a == X && b == Y) || (step == 1 && a == Y && b == X)
    {
        var temp := a;
        a := b;
        b := temp;
        step := step + 1;
    }

    x := a;
    y := b;
}
